function syncBoomSelectors(){for(const [field,picker] of [['boom','boomSelect'],['boom2','boomSelect2']]){const raw=$(field).value,value=Number(raw),found=raw===''?null:Array.from($(picker).options).find(o=>o.value!==''&&Math.abs(Number(o.value)-value)<1e-8);$(picker).value=found?.value||'';$(picker).classList.toggle('auto-filled',$(field).dataset.auto==='true');}}
