function positionSummaryHTML(pos){if(pos.patternMissing)return '<b>Verificación pendiente</b><br>Completá la configuración de la grúa en el selector resaltado. Los datos de esta posición se conservan.';if(!pos.result)return `<b>${pos.geometryPreview?'Geometría calculada · capacidad sin verificar':pos.estimate?'Estimación · sin verificar':'Sin verificar'}</b><br>${esc(pos.error||'')}${geometryPreviewHTML(pos)}${pos.estimate?`<p><b>Capacidad estimada: ${fmt(pos.estimate.capacity/1000,3)} tn</b> · referencia de tabla ${fmt(pos.estimate.reference.capacity/1000,3)} tn a R ${fmt(pos.estimate.reference.radius,3)} m / L ${fmt(pos.estimate.reference.boom,3)} m.<br>Estimación matemática; no aprueba el 75%.</p>`:''}`;const r=pos.result;return `<b>${r.pass?'✓ Cumple':'× No cumple'} · uso ${fmt(r.percent,2)}%</b><br>Capacidad de tabla <b>${fmt(r.capacity/1000,3)} tn</b> · disponible ${fmt(r.netCapacity/1000,3)} tn.<br>θ de pluma ${r.angleApproximate?'≈ ':''}${fmt(r.angle,2)}°.${pos.setupError?'<br>'+esc(pos.setupError):''}${pos.auto.boom||pos.auto.radius?'<br>R/L propuestos por tabla; revisá que correspondan al izaje real.':''}`;}
