$('importPlan').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error('Archivo demasiado grande.');const obj=JSON.parse(await file.text());if(!['izajelab-plan-v1','izajelab-plan-v2','izajelab-plan-v3','izajelab-plan-v4'].includes(obj.format)||!obj.inputs)throw Error('Formato no reconocido.');const data=obj.inputs;if(typeof data!=='object'||Array.isArray(data))throw Error('Datos de análisis inválidos.');const importedCrane=CRANES.find(c=>c.id===(obj.crane?.id||data.craneModel));if(!importedCrane)throw Error('La grúa de este análisis ya no está en el catálogo. Usá uno de los tres modelos del proyecto.');if(!importedCrane.configs.some(f=>f.id===data.config))throw Error('La configuración del análisis no está en la tabla de esta grúa.');const importedConfig=importedCrane.configs.find(f=>f.id===data.config),importedFamily=importedCrane.craneType==='crawler'?[importedConfig]:importedCrane.configs.filter(f=>f.outriggers===importedConfig.outriggers&&f.sector===importedConfig.sector&&f.counterweightKg===importedConfig.counterweightKg&&f.carbodyCounterweightKg===importedConfig.carbodyCounterweightKg);for(const [i,id] of ['boom','boom2'].entries()){const value=data[id];if(value!==undefined&&value!==null&&value!==''&&!importedFamily.some(f=>f.booms.some(L=>Math.abs(L-Number(value))<1e-8)))throw Error('El análisis contiene una pluma no tabulada ('+value+' m) en posición '+(i+1)+'. Elegí una longitud de la lista.');}if(data.unit!==undefined&&!['kg','t'].includes(data.unit))throw Error('Unidad del análisis inválida: usar kg o t.');for(const id of UNIT_FIELDS)if(data[id]!==undefined&&!['kg','t'].includes(data[id]))throw Error('Unidad del análisis inválida: usar kg o t.');if(data.equalized!==undefined&&typeof data.equalized!=='boolean')throw Error('El reparto de ramales debe ser verdadero o falso, sin texto.');if(obj.autoFields!==undefined&&(!Array.isArray(obj.autoFields)||obj.autoFields.some(id=>!AUTO_FIELDS.includes(id))))throw Error('Campos automáticos del análisis inválidos.');clearAuto();for(const ids of POSITION_FIELDS)for(const id of Object.values(ids))$(id).value='';
 if(obj.format==='izajelab-plan-v1'){data.hookHeight=Number(data.landingHeight||0)+Number(data.loadHeight||0)+Number(data.rigHeight||0);if(data.unit==='t')for(const k of ['hook','rig','other','deduction'])data[k]=Number(data[k])*1000;}
 for(const id of UNIT_FIELDS)$(id).value=data[id]||'kg';rememberUnits();selectCrane(obj.crane?.id||data.craneModel,data.config);
 for(const id of fields){if(['brand','craneModel','config','confirmed'].includes(id)||!Object.hasOwn(data,id))continue;const el=$(id);if(el.type==='checkbox')el.checked=Boolean(data[id]);else el.value=String(data[id]);}$('confirmed').checked=false;const importedChoice=data.rigChoice||RIGGING_CHOICES.find(c=>c.hitch===data.hitch)?.id;if(importedChoice)selectRigging(importedChoice);for(const id of obj.autoFields||[])if(AUTO_FIELDS.includes(id))$(id).dataset.auto='true';$('cargoDimensions').open=['cargoLength','cargoWidth','cargoHeight'].some(id=>$(id).value!=='');rememberUnits();slingUI();updateWeight();evaluate();evaluateSling();tab('home');toast(obj.format==='izajelab-plan-v4'?'Análisis de dos posiciones recalculado.':'Análisis anterior: completá los datos mínimos de posición 2 para verificar el plan.');
 }catch(err){toast(err.message);}finally{e.target.value='';}};
